<section class="showcase-section" id="showcase" aria-labelledby="showcase-title" data-slider data-autoplay="true">
    <div class="container showcase-inner">
        <div class="showcase-heading">
            <div>
                <p class="eyebrow eyebrow-on-dark">A platform taking shape</p>
                <h2 id="showcase-title">See the assessment journey ahead.</h2>
            </div>
            <p>Interface concepts for the next product phases. These are illustrative previews, not live ExamCore features.</p>
        </div>

        <div class="slider" aria-roledescription="carousel" aria-label="Planned ExamCore product interface concepts" tabindex="0" data-slider-track>
            <article class="slide is-active" aria-roledescription="slide" aria-label="1 of 4: Take an exam" data-slide>
                <div class="slide-title"><span>01</span><h3>Take an Exam</h3></div>
                <div class="browser-frame" role="img" aria-label="Illustrative exam screen preview with question and answer options">
                    <div class="browser-chrome"><span></span><span></span><span></span><i>examcore / assessment-preview</i></div>
                    <div class="mock-exam-screen">
                        <div class="mock-side-rail"><strong>EC</strong><span>01</span><span>02</span><span class="selected">03</span><span>04</span></div>
                        <div class="mock-exam-main"><div class="mock-topline"><span>FOUNDATIONS OF BIOLOGY</span><span class="mock-timer">24:16</span></div><div class="mock-progress"><i></i></div><p class="mock-question-count">QUESTION 03 OF 24</p><h4>Which cell structure is primarily responsible for producing ATP?</h4><div class="mock-answer chosen">Mitochondrion <b>Selected</b></div><div class="mock-answer">Ribosome</div><div class="mock-answer">Golgi apparatus</div><div class="mock-answer">Lysosome</div></div>
                    </div>
                </div>
            </article>
            <article class="slide" aria-roledescription="slide" aria-label="2 of 4: Review results" data-slide hidden>
                <div class="slide-title"><span>02</span><h3>Review Results</h3></div>
                <div class="browser-frame" role="img" aria-label="Illustrative results summary screen with score and review details">
                    <div class="browser-chrome"><span></span><span></span><span></span><i>examcore / results-preview</i></div>
                    <div class="mock-results-screen"><div class="mock-appbar"><strong>Assessment results</strong><span>DEMO RECORD</span></div><div class="mock-result-body"><div class="score-ring"><span>84<small>%</small></span></div><div class="mock-result-copy"><p class="mock-question-count">COMPLETION SUMMARY</p><h4>Good work, learner.</h4><p>Illustrative score review and feedback summary.</p><div class="score-line"><span>Knowledge checks</span><i><b style="width:84%"></b></i><strong>84%</strong></div><div class="score-line"><span>Applied reasoning</span><i><b style="width:76%"></b></i><strong>76%</strong></div></div></div></div>
                </div>
            </article>
            <article class="slide" aria-roledescription="slide" aria-label="3 of 4: Build a question bank" data-slide hidden>
                <div class="slide-title"><span>03</span><h3>Build a Question Bank</h3></div>
                <div class="browser-frame" role="img" aria-label="Illustrative question library screen with searchable question rows">
                    <div class="browser-chrome"><span></span><span></span><span></span><i>examcore / library-preview</i></div>
                    <div class="mock-library-screen"><div class="mock-appbar"><strong>Question library</strong><span class="mock-small-button">＋ Add question</span></div><div class="mock-library-toolbar"><span>⌕ &nbsp; Search by topic or keyword</span><span>All subjects &nbsp;⌄</span></div><div class="mock-table-head"><span>QUESTION</span><span>SUBJECT</span><span>TYPE</span></div><div class="mock-table-row"><b>Cellular energy and ATP</b><span>Biology</span><em>Multiple choice</em></div><div class="mock-table-row"><b>Interpreting a data set</b><span>Mathematics</span><em>Short answer</em></div><div class="mock-table-row"><b>Forces in equilibrium</b><span>Physics</span><em>Multiple choice</em></div><div class="mock-table-row"><b>Reading for inference</b><span>English</span><em>Essay</em></div></div>
                </div>
            </article>
            <article class="slide" aria-roledescription="slide" aria-label="4 of 4: Explore assessment insights" data-slide hidden>
                <div class="slide-title"><span>04</span><h3>Explore Assessment Insights</h3></div>
                <div class="browser-frame" role="img" aria-label="Illustrative analytics dashboard with completion and score charts">
                    <div class="browser-chrome"><span></span><span></span><span></span><i>examcore / insights-preview</i></div>
                    <div class="mock-analytics-screen"><div class="mock-appbar"><strong>Assessment overview</strong><span>LAST 30 DAYS &nbsp;⌄</span></div><div class="metric-row"><div><small>INVITED</small><strong>1,248</strong><span>Illustrative</span></div><div><small>COMPLETED</small><strong>1,082</strong><span>Illustrative</span></div><div><small>AVERAGE SCORE</small><strong>78%</strong><span>Illustrative</span></div></div><div class="mock-chart"><div class="chart-legend"><span>Completion trend</span><span class="legend-dot"></span></div><div class="chart-bars"><i style="height:42%"></i><i style="height:55%"></i><i style="height:49%"></i><i style="height:68%"></i><i style="height:59%"></i><i style="height:78%"></i><i style="height:70%"></i><i style="height:92%"></i><i style="height:83%"></i><i style="height:100%"></i></div><div class="chart-labels"><span>WEEK 1</span><span>WEEK 2</span><span>WEEK 3</span><span>WEEK 4</span></div></div></div>
                </div>
            </article>
        </div>

        <div class="slider-controls">
            <div class="slider-arrows">
                <button class="icon-button slider-arrow" type="button" aria-label="Previous preview" data-slide-prev><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 12H5m7 7-7-7 7-7"/></svg></button>
                <button class="icon-button slider-arrow" type="button" aria-label="Next preview" data-slide-next><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-7-7 7 7-7 7"/></svg></button>
            </div>
            <div class="slider-dots" role="group" aria-label="Choose a product preview">
                <button type="button" class="is-active" aria-label="Show Take an Exam preview" aria-pressed="true" data-slide-dot="0"></button>
                <button type="button" aria-label="Show Review Results preview" aria-pressed="false" data-slide-dot="1"></button>
                <button type="button" aria-label="Show Question Bank preview" aria-pressed="false" data-slide-dot="2"></button>
                <button type="button" aria-label="Show Assessment Insights preview" aria-pressed="false" data-slide-dot="3"></button>
            </div>
            <p class="slider-note" aria-live="polite" data-slide-status>Preview 1 of 4</p>
        </div>
    </div>
</section>